messages.content:
Tool response:
Tool: generate_delinquency_report
Description: Generate Delinquency Report
Parameters:
    {
      "type": "object",
      "properties": {
        "portfolio_name": {
          "type": "string",
          "description": "Name of the portfolio to generate report for",
          "title": "Portfolio Name"
        },
        "report_date": {
          "type": "string",
          "format": "date",
          "description": "Report date in YYYY-MM-DD format",
          "title": "Report Date"
        },
        "min_balance": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum outstanding balance threshold (default: 500)",
          "default": 500.0,
          "title": "Min Balance"
        }
      },
      "required": [
        "portfolio_name",
        "report_date"
      ]
    }
